Q: Warning: Detected unsettled top-level await A: <pre><code>async function dummy() {
    return new Promise(async (resolve, reject) =&gt; {
        console.log('dummy begin');
        await new Promise(resolve =&gt; setTimeout(resolve, 1000));
        console.log('dummy end');
        resolve();
    });
}
</code></pre>
